Voici un exemple de code pour un bot Discord avec une commande de bannissement utilisant Discord.js v14 :

```javascript
const { Client, GatewayIntentBits, Events, EmbedBuilder } = require('discord.js');

// Créez une instance du client Discord
const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent
  ]
});

// Connectez le client au serveur Discord
client.once(Events.ClientReady, () => {
  console.log('Ready! My user ID is: ', client.user.id);
});

// Commande de bannissement
client.command({
  name: 'ban',
  description: 'Bannir un utilisateur du serveur',
  options: [
    {
      name: 'utilisateur',
      description: 'Le membre à bannir',
      type: Discord.ApplicationCommandOptionType.User,
      required: true
    },
    {
      name: 'raison',
      description: 'La raison du bannissement',
      type: Discord.ApplicationCommandOptionType.String,
      required: false
    }
  ],
  execute(interaction) {
    const user = interaction.options.getUser('utilisateur');
    const reason = interaction.options.getString('raison') || 'Aucune raison fournie';

    // Vérifiez si l'utilisateur à bannir a les permissions nécessaires
    if (!interaction.memberPermissions.has(Discord.PermissionFlagsBits.BanMembers)) {
      interaction.reply({
        content: 'Vous n'avez pas la permission de bannir les utilisateurs.',
        ephemeral: true
      });
      return;
    }

    // Vérifiez si l'utilisateur à bannir est dans le même serveur que le bot
    if (interaction.guild.members.me.hasPermission(Discord.PermissionFlagsBits.BanMembers) && user.id !== interaction.user.id) {
      // Bannissez l'utilisateur
      interaction.guild.members.ban(user, { reason });

      // Répondez à l'interaction
      interaction.reply({
        content: `**${user.tag}** a été banni avec la raison: ${reason}`
      });
    } else {
      interaction.reply({
        content: 'Je ne peux pas bannir d\'utilisateurs hors de ce serveur.',
        ephemeral: true
      });
    }
  }
});

// Connexion du client au serveur Discord
client.login(process.env.TOKEN);
```

Remarque: Assurez-vous d'avoir créé un fichier `.env` dans lequel vous aurez enregistré la clé d'API Discord en tant que variable d'environnement `TOKEN`. Cela vous permettra de garder votre clé d'API en sécurité dans votre projet.  Ne jamais inclure votre clé d'API dans votre code.

