Voici un exemple de code C qui utilise la bibliothèque SDL pour créer le jeu du serpent :

```c
#include <stdio.h>
#include <stdlib.h>
#include <SDL2/SDL.h>

#define WINDOW_WIDTH 800
#define WINDOW_HEIGHT 600

// Déclaration des constantes
const int SNAKE_SPEED = 10;

// Déclaration des structures
typedef struct {
    int x, y;
} Point;

typedef struct {
    Point head;
    int length;
    Point *body;
} Snake;

// Fonctions

void initWindow(SDL_Window **window, SDL_Renderer **renderer) {
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        printf("SDL initialization failed: %s\n", SDL_GetError());
        exit(EXIT_FAILURE);
    }

    *window = SDL_CreateWindow("Snake Game", SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED, WINDOW_WIDTH, WINDOW_HEIGHT, SDL_WINDOW_SHOWN);
    if (*window == NULL) {
        printf("Window creation failed: %s\n", SDL_GetError());
        SDL_Quit();
        exit(EXIT_FAILURE);
    }

    *renderer = SDL_CreateRenderer(*window, -1, SDL_RENDERER_ACCELERATED);
    if (*renderer == NULL) {
        printf("Renderer creation failed: %s\n", SDL_GetError());
        SDL_DestroyWindow(*window);
        SDL_Quit();
        exit(EXIT_FAILURE);
    }
}

void closeWindow(SDL_Window *window, SDL_Renderer *renderer) {
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();
}

void loadResources(SDL_Renderer *renderer, char **snakeHeadTexture, char **snakeBodyTexture, char **foodTexture, char **wallTexture) {
    // Charger les textures
    *snakeHeadTexture = SDL_LoadBMP("snake_head.bmp");
    *snakeBodyTexture = SDL_LoadBMP("snake_body.bmp");
    *foodTexture = SDL_LoadBMP("food.bmp");
    *wallTexture = SDL_LoadBMP("wall.bmp");

    if (*snakeHeadTexture == NULL || *snakeBodyTexture == NULL || *foodTexture == NULL || *wallTexture == NULL) {
        printf("Failed to load resources: %s\n", SDL_GetError());
        exit(EXIT_FAILURE);
    }
}

void freeResources(char *snakeHeadTexture, char *snakeBodyTexture, char *foodTexture, char *wallTexture) {
    SDL_free(snakeHeadTexture);
    SDL_free(snakeBodyTexture);
    SDL_free(foodTexture);
    SDL_free(wallTexture);
}

void drawWall(SDL_Renderer *renderer, int x, int y) {
    SDL_Rect rect = { x, y, 20, 20 };
    SDL_RenderCopy(renderer, wallTexture, NULL, &rect);
}

void drawFood(SDL_Renderer *renderer, int x, int y) {
    SDL_Rect rect = { x, y, 20, 20 };
    SDL_RenderCopy(renderer, foodTexture, NULL, &rect);
}

void drawSnake(SDL_Renderer *renderer, Snake *snake) {
    for (int I = 0; I < snake->length; i++) {
        SDL_Rect rect = { snake->body[i].x, snake->body[i].y, 20, 20 };
        if (i == 0) {
            SDL_RenderCopy(renderer, snakeHeadTexture, NULL, &rect);
        } else {
            SDL_RenderCopy(renderer, snakeBodyTexture, NULL, &rect);
        }
    }
}

void updateSnake(Snake *snake, int direction) {
    Point head = snake->head;
    int x = head.x;
    int y = head.y;

    switch (direction) {
        case SDL_SCANCODE_UP:
            y -= SNAKE_SPEED;
            break;
        case SDL_SCANCODE_DOWN:
            y += SNAKE_SPEED;
            break;
        case SDL_SCANCODE_LEFT:
            x -= SNAKE_Speed;
            break;
        case SDL_SCANCODE_RIGHT:
            x += SNAKE_Speed;
            break;
    }

    // Vérifier si la tête du serpent touche un mur ou sa propre queue
    if (x < 0 || x >= WINDOW_WIDTH / 20 || y < 0 || y >= WINDOW_HEIGHT / 20) {
        // Mort du serpent
        snake->length = 1;
        snake->head.x = 10 * WINDOW_WIDTH / 20;
        snake->head.y = 10 * WINDOW_HEIGHT / 20;
        snake->body = (Point *)realloc(snake->body, sizeof(Point));
    } else {
        for (int I = snake->length - 2; I >= 0; i--) {
            snake->body[i + 1] = snake->body[i];
        }

        snake->body[0] = snake->head;

        if (snake->head.x == snake->body[1].x && snake->head.y == snake->body[1].y) {
            // Croissance du serpent
            snake->length++;
            Point food = { (rand() % (WINDOW_WIDTH / 20)) * 20, (rand() % (WINDOW_HEIGHT / 20)) * 20 };
            bool overlap = false;

            for (int I = 1; I < snake->length; i++) {
                if (snake->body[i].x == food.x && snake->body[i].y == food.y) {
                    overlap = true;
                    break;
                }
            }

            if (!overlap) {
                snake->body = (Point *)realloc(snake->body, sizeof(Point) * snake->length);
                snake->head = food;
            }
        }
    }
}

int main(int argc, char *argv[]) {
    SDL_Window *window;
    SDL_Renderer *renderer;

    char *snakeHeadTexture = NULL, *snakeBodyTexture = NULL, *foodTexture = NULL, *wallTexture = NULL;

    Snake snake = { { 10 * WINDOW_WIDTH / 20, 10 * WINDOW_HEIGHT / 20 }, 1, (Point *)malloc(sizeof(Point)) };

    initWindow(&window, &renderer);

    loadResources(renderer, &snakeHeadTexture, &snakeBodyTexture, &foodTexture, &wallTexture);

    while (1) {
        SDL_Event event;

        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                closeWindow(window, renderer);
                freeResources(snakeHeadTexture, snakeBodyTexture, foodTexture, wallTexture);
                return 0;
            }

            switch (event.type) {
                case SDL_KEYDOWN:
                    updateSnake(&snake, event.key.keysym.sym);
                    break;
            }
        }

        // Nettoyer l'écran
        SDL_SetRenderDrawColor(renderer, 0x00, 0x00, 0x00, 0xFF);
        SDL_RenderClear(renderer);

        // Dessiner les murs
        for (int I = 0; I < 40; i++) {
            drawWall(renderer, I * 20, 0);
            drawWall(renderer, I * 20, WINDOW_HEIGHT / 20);
        }

        for (int I = 0; I < 20; i++) {
            drawWall(renderer, 0, I * 20);
            drawWall(renderer, WINDOW_WIDTH / 20, I * 20);
        }

        // Dessiner la nourriture
        drawFood(renderer, snake.head.x, snake.head.y);

        // Dessiner le serpent
        drawSnake(renderer, &snake);

        // Rafraichir l'écran
        SDL_RenderPresent(renderer);
    }

    closeWindow(window, renderer);

    freeResources(snakeHeadTexture, snakeBodyTexture, foodTexture, wallTexture);

    return 0;
}
```

